        [Fact]
        public void ExceedanceWeibullProblematicFullWorkflow()

        {
            //// Arrange
            var windDirList = new List<int>() { 0, 45, 90, 135, 180, 225, 270, 315 };

            var z0 = 1;
            var uref = 5;
            var zref = 10;

            var bcond = new ABL(0, uref, zref, z0, 0);

            string epw = DownloadAhmedabadEPW();
            Weather weather = new Weather(epw);

            Vector3d[,] vecs = new Vector3d[problematicArr.Length, windDirList.Count];
            for (int j = 0; j < problematicArr.Length; j++)
            {
                for (int i = 0; i < windDirList.Count; i++)
                {
                    vecs[j, i] = problematicArr[j];
                }
            }
              ;

            var workingdir = @"C:\Testing\";
            if (!Directory.Exists(workingdir)) { Directory.CreateDirectory(workingdir); }
            ;
            var points = Enumerable.Repeat(new Point3d(1, 1, 2), 981).ToArray(); ;
            var mdv = new MultiDirectionalVelocities(workingdir, windDirList.ToArray(), vecs, true, true);

            //// Act
            ///
            var bcColl = new BCCollection(bcond);

            var wfs = new WindFactorsSpatial(workingdir, bcColl, mdv, points.ToList(), false, true);

            //// Assert (Taken from Eddy demo file)

            var wft = new WindFactorsTemporal(workingdir, bcColl, weather, wfs, points.ToList(), false, true);

            var wcw = new WindComfortWeibull(wft, PedCmftMetric.NEN8100Comfort);

            // I just wanna know if the Weibull estimator converges for large arrays with 0's
            var test = 0.0;
            Assert.Equal(test, 0.0);
        }

