        public static bool CheckAllElementsEqual<T>(T[,] array, T valueToCheck)
        {
            for (int i = 0; i < array.GetLength(0); i++)
            {
                for (int j = 0; j < array.GetLength(1); j++)
                {
                    if (!EqualsWithPrecision(array[i, j], valueToCheck))
                    {
                        return false;
                    }
                }
            }
            return true;
        }

        public static bool CheckAllElementsEqual<T>(T[] array, T valueToCheck)
        {
            for (int j = 0; j < array.Length; j++)
            {
                if (!EqualsWithPrecision(array[j], valueToCheck))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool EqualsWithPrecision<T>(T a, T b)
        {
            if (typeof(T) == typeof(double))
            {
                // Adjust precision as necessary
                double tolerance = 1e-6;
                return Math.Abs(Convert.ToDouble(a) - Convert.ToDouble(b)) < tolerance;
            }
            else if (typeof(T) == typeof(float))
            {
                // Adjust precision as necessary
                float tolerance = 1e-6f;
                return Math.Abs(Convert.ToSingle(a) - Convert.ToSingle(b)) < tolerance;
            }
            else
            {
                return Equals(a, b);
            }
        }

